import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Value-per-weight ratio of each candidate, scaled by the best ratio among candidates."""
    d = values / np.maximum(weights, 1)
    return d / (d.max() + 1e-9)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Candidate value divided by the knapsack's total capacity."""
    return values / max(capacity, 1)
